
.sport-container {
  background: linear-gradient(to bottom, #23263c, #190f25);
  display: flex;
  align-items: center;
  justify-content: center;
  .sports-iframe {
    width: 100%;
    min-height: 100vh;
    overflow: auto !important;
  }
}
